// Follow the same labelled tabs a user uses; never force-click hidden controls.
export async function revealPanel(page, target) {
  await target.waitFor({ state: 'attached' });
  const tabs = await target.evaluate(element => {
    const ids = [];
    for (let node = element; node; node = node.parentElement) {
      if (node.getAttribute('role') === 'tabpanel') ids.unshift(node.getAttribute('aria-labelledby'));
    }
    return ids.filter(Boolean);
  });
  for (const id of tabs) {
    // IDs are generated by the application, not by source content.
    const button = page.locator(`[role="tab"][id=${JSON.stringify(id)}]`);
    if (await button.count() && await button.isVisible() && await button.getAttribute('aria-selected') !== 'true') await button.click();
  }
  await target.waitFor({ state: 'visible' });
}
